private fun resolveTableAndColumn(
        filterColumn: String,
        table: AdminJdbcTable,
        jdbcTables: List<AdminJdbcTable>,
    ): Pair<AdminJdbcTable?, ColumnSet?> {
        val isNestedColumn = filterColumn.contains(".")

        val filterTable =
            if (isNestedColumn) {
                val paths = filterColumn.split(".")
                jdbcTables.find { it.getTableName() == paths[paths.size - 2] }
            } else {
                table
            }

        val columnSet =
            if (isNestedColumn) {
                val paths = filterColumn.split(".")
                filterTable?.getAllColumns()?.find { it.columnName == paths.last() }
            } else {
                filterTable?.getAllColumns()?.find { it.columnName == filterColumn }
            }

        return Pair(filterTable, columnSet)
    }

suspend fun ApplicationCall.badRequest(
    message: String,
    throwable: Throwable? = null,
) {
    respondText(status = HttpStatusCode.BadRequest, contentType = ContentType.Text.Html) {
        generateErrorHtml(
            "400 - Bad Request",
            if (DynamicConfiguration.debugMode) message else "",
            throwable?.stackTraceToString(),
        )
    }
}

private suspend fun handleSaveThumbnail(objectId: Int, events: List<ColumnEvent>) {
        events.find { it.columnSet.columnName == "file" }?.let {
            if (it.changed.not()) return
            val filEvent = it.value as? FileEvent
            filEvent?.let { event ->
                val file = File(MEDIA_PATH, "thumbnail${objectId}${System.currentTimeMillis()}.jpeg").apply {
                    createNewFile()
                }
                val videoFile = File(MEDIA_PATH, event.fileName)
                println(videoFile.path)
                println(file.path)
                generateThumbnailFromVideo(
                    videoFile,
                    file,
                )
                tasksService.updateThumbnail(
                    objectId,
                    file.name
                )
            }
        }
    }

internal suspend fun ApplicationCall.handleAddNewItem(
    panels: List<AdminPanel>,
    panelGroups: List<PanelGroup>,
) {
    val pluralName = parameters["pluralName"]
    val panel = panels.find { it.getPluralName() == pluralName }
    if (panel == null || panel.isShowInAdminPanel().not()) {
        notFound("No table found with plural name: $pluralName")
    } else {
        checkHasRole(panel) {
            when (panel) {
                is AdminJdbcTable -> handleJdbcAddView(table = panel, panels = panels, panelGroups = panelGroups)
                is AdminMongoCollection -> handleNoSqlAddView(panel = panel, panelGroups = panelGroups)
            }
        }
    }
}

private fun validateOrder(
        order: Order?,
        columnNames: List<String>,
    ) {
        if (order != null) {
            if (order.name !in columnNames) {
                throw IllegalArgumentException(
                    INVALID_COLUMN_MESSAGE.format(
                        order.name,
                        DefaultOrder::class.simpleName,
                    ),
                )
            }
            if (order.direction.lowercase() !in VALID_ORDER_DIRECTIONS) {
                throw IllegalArgumentException(INVALID_ORDER_DIRECTION_MESSAGE.format(order.direction))
            }
        }
    }

fun registerCustomAdminAction(customAction: KtorAdminAction) {
        if (_customActions.any { it.key == customAction.key }) {
            throw IllegalArgumentException("A custom action with key '${customAction.key}' is already registered.")
        }
        _customActions.add(customAction)
    }

internal inline fun <D> Response<D>.onError(action: (List<ErrorResponse>, values: Map<String, String?>) -> Unit): Response<D> =
    when (this) {
        is Response.Error -> {
            action(errors, values)
            this
        }

        else -> this
    }

private fun validateRichEditor(
        hasRichEditor: Boolean,
        columnType: ColumnType,
    ) {
        if (hasRichEditor && columnType != ColumnType.STRING) {
            throw IllegalArgumentException("Rich editor can only be used with columns of type STRING.")
        }
    }

private fun validateManyToManyTables(
    columnsWithReferences: List<ColumnSet>,
    tables: List<AdminJdbcTable>,
) {
    val missingJoinTables =
        columnsWithReferences
            .map { (it.reference as Reference.ManyToMany).joinTable }
            .filter { joinTable ->
                tables.none { it.getTableName() == joinTable }
            }

    if (missingJoinTables.isNotEmpty()) {
        throw IllegalArgumentException(
            "Error: The following join tables are missing from the schema: ${missingJoinTables.joinToString()}",
        )
    }
}

private fun File.requiredSave(path: String): File {
        if (exists().not()) {
            createNewFile()
            return this
        }
        var counter = 1
        var file = this
        val baseName = nameWithoutExtension
        while (file.exists()) {
            val extension = file.extension
            val filename = "$baseName($counter).$extension"
            file = File("$path/$filename")
            counter++
        }
        file.createNewFile()
        return file
    }

internal suspend fun ApplicationCall.checkHasRole(
    panel: AdminPanel,
    build: suspend ApplicationCall.() -> Unit,
) {
    val user = principal<KtorAdminPrincipal>()
    val accessRoles = panel.getAccessRoles()
    if (accessRoles != null && (user == null || user.roles?.any { it in accessRoles } != true)) {
        forbidden("Access denied: You do not have permission to perform this action.")
        return
    }
    build.invoke(this)
}

private fun validateEnumeration(
        value: String,
        enumValues: List<String>?,
        translator: KtorAdminTranslator,
    ): String? {
        if (enumValues == null || value !in enumValues) {
            return translator.translate(
                KtorAdminTranslator.Keys.ERROR_INVALID_ENUMERATION,
                mapOf("values" to (enumValues?.joinToString() ?: "")),
            )
        }
        return null
    }

override suspend fun onAuthenticate(context: AuthenticationContext) {
        val call = context.call
        val token = call.getTokenFromSessions()

        if (token != null) {
            val principal = tokenAuthenticationFunction.invoke(call, token)
            if (principal != null) {
                context.principal(name, principal)
                return
            } else {
                call.sessions.clear(USER_SESSIONS)
                loginWithParameters(call, context)
            }
        } else {
            loginWithParameters(call, context)
        }
    }

private fun validateStatusColors(
        columnType: ColumnType,
        statusColors: List<String>?,
        enumValues: List<String>?,
        name: String,
    ) {
        if (columnType != ColumnType.ENUMERATION && statusColors != null) {
            throw IllegalArgumentException("StatusStyle can only be used with ENUMERATION column types.")
        }

        val hexColorPattern = "^#([A-Fa-f0-9]{6})$".toRegex()
        if ((statusColors != null && enumValues != null) &&
            (
                statusColors.count() != enumValues.count() ||
                    statusColors.any { !hexColorPattern.matches(it) }
            )
        ) {
            throw IllegalArgumentException(
                "($name) Invalid status colors: The number of status colors must match the number of " +
                    "enumeration values, and all colors must be valid hex codes (excluding #000000).",
            )
        }
    }

private suspend fun ApplicationCall.getFieldOrder(table: AdminMongoCollection): Order? {
    val orderDirection = parameters["orderDirection"]?.takeIf { it.isNotEmpty() } ?: "ASC"
    if (orderDirection.lowercase() !in listOf("asc", "desc")) {
        badRequest("Invalid order direction '$orderDirection'. Valid values are 'asc' or 'desc'.")
    }

    return parameters["order"]?.takeIf { it.isNotEmpty() }?.let { orderField ->
        if (orderField !in table.getAllFields().map { it.fieldName }) {
            badRequest(
                "The column '$orderField' specified in the order does not exist in the collection. Please provide a valid field name for ordering.",
            )
        }
        Order(orderField, orderDirection)
    } ?: table.getDefaultOrder()
}

internal fun Map<String, Any>.addCommonUpsertModels(
    table: AdminMongoCollection,
    username: String?,
): Map<String, Any> =
    toMutableMap()
        .apply {
            if (table.getAllAllowToShowFieldsInUpsert().any { it.hasRichEditor }) {
                val json =
                    Json {
                        encodeDefaults = true
                    }
                val config = json.encodeToString(DynamicConfiguration.tinyMCEConfig)
                set("tinyMCEConfig", config)
            }
            username?.let { put("username", it) }
        }.toMap()

private fun registerCustomPageEntry(entry: CustomPageEntry) {
        if (_customPageEntries.containsKey(entry.path)) {
            throw IllegalStateException("A custom page with path '${entry.path}' is already registered.")
        }
        _customPageEntries[entry.path] = entry
    }

internal inline fun <D> Response<D>.onError(action: (requestId: String?, List<ErrorResponse>, values: Map<String, String?>) -> Unit): Response<D> =
