override suspend fun onUpdateJdbcData(tableName: String, objectPrimaryKey: String, events: List<ColumnEvent>) {
        if (tableName == "tasks") {
            handleSaveThumbnail(objectPrimaryKey.toInt(), events)
        }
    }

internal fun ResultSet.getTypedValue(
    type: ColumnType,
    name: String,
): Any? =
    when (type) {
        ColumnType.LONG, ColumnType.ULONG -> getObject(name)?.toString()?.toLongOrNull()
        ColumnType.INTEGER, ColumnType.UINTEGER -> getObject(name)?.toString()?.toIntOrNull()
        ColumnType.SHORT, ColumnType.USHORT -> getObject(name)?.toString()?.toShortOrNull()
        ColumnType.FLOAT -> getObject(name)?.toString()?.toFloatOrNull()
        ColumnType.DOUBLE -> getObject(name)?.toString()?.toDoubleOrNull()

        else -> getObject(name)
    }

internal suspend fun redirectToLogin(
    call: ApplicationCall,
    requestId: String?,
) {
    val originUrl =
        if (call.request.uri.startsWith("/${DynamicConfiguration.adminPath}/login")) {
            call.setFlashSessionsAndRedirect(
                requestId,
                listOf(),
                emptyMap(),
            )
            URLBuilder(call.request.uri).parameters["origin"].orEmpty()
        } else {
            URLBuilder(call.baseUrl + call.request.uri)
                .apply {
                    if (parameters.contains("origin")) {
                        parameters.remove("origin")
                    }
                }.buildString()
        }
    call.respondRedirect("${call.baseUrl}/${DynamicConfiguration.adminPath}/login?origin=$originUrl")
}

override fun map(value: Any?): Any? {
        return when (value) {
            is Int -> value.times(2)
            else -> null
        }
    }

override suspend fun performAction(
        name: String,
        selectedIds: List<String>,
    ) {
        when (panel) {
            is AdminJdbcTable -> {
                // Deletes rows from a JDBC-based table
                deleteJdbcFiles(panel, selectedIds)
                JdbcQueriesRepository.deleteRows(panel, selectedIds)
            }

            is AdminMongoCollection -> {
                // Deletes documents from a MongoDB collection
                deleteMongoFiles(panel, selectedIds)
                MongoClientRepository.deleteRows(panel, selectedIds)
            }
        }

        // Notify event listeners about the deletion
        sendEvent(name, selectedIds)
    }

private fun validateDisplayFormat(
        displayFormat: String?,
        columnNames: List<String>,
        className: String,
    ) {
        if (displayFormat != null) {
            val invalidColumns =
                displayFormat
                    .extractTextInCurlyBraces()
                    .map { it.split(".").first() }
                    .filter { it !in columnNames }

            if (invalidColumns.isNotEmpty()) {
                throw IllegalArgumentException(
                    "($className) The following columns in display format do not exist: ${invalidColumns.joinToString()}",
                )
            }
        }
    }

private fun validateAutoComplete(
        hasAutoComplete: Boolean,
        reference: Reference?,
    ) {
        if (hasAutoComplete && reference == null) {
            throw IllegalArgumentException(
                "@AutoComplete can only be used on columns with a reference (ManyToOneReferences or OneToOneReferences).",
            )
        }
        if (hasAutoComplete && reference is Reference.ManyToMany) {
            throw IllegalArgumentException(
                "@AutoComplete cannot be used with ManyToMany references. Use a standard select for ManyToMany fields.",
            )
        }
    }

private fun AdminMongoCollection.getPrimaryKeyFilter(primaryKey: String) =
        if (getPrimaryKeyField().type == FieldType.ObjectId || getPrimaryKey() == "_id") {
            eq(getPrimaryKey(), ObjectId(primaryKey))
        } else {
            eq(getPrimaryKey(), primaryKey)
        }

override suspend fun onInsertJdbcData(
        tableName: String,
        objectPrimaryKey: String,
        events: List<ColumnEvent>
    ) {
        if (tableName == "tasks") {
            handleSaveThumbnail(objectPrimaryKey.toInt(), events)
        }
    }
